type menuItemT =
  | allowedPrimitiveT
  | itemT
  | (itemT & {
      variant?: 'default' | 'destructive'
      shortcut?: string
      disabled?: boolean
    })

type menuGroupT = {
  group: string
  items: menuItemT[]
  className?: string
  groupLabelCls?: string
}

type subMenuT = {
  submenu: string
  items: (menuItemT | menuGroupT)[]
  triggerCls?: string
  contentCls?: string
}

type menuItemsT = (menuItemT | menuGroupT | subMenuT)[]

type menuInputItemT =
  | allowedPrimitiveT
  | itemT
  | (itemT & {
      disabled?: boolean
    })

type menuInputGroupT = {
  group: string
  items: menuInputItemT[]
  className?: string
  groupLabelCls?: string
}

type inputSubMenuT = {
  submenu: string
  items: (menuInputItemT | menuInputGroupT)[]
  triggerCls?: string
  contentCls?: string
}

type menuInputItemsT = (menuInputItemT | menuInputGroupT | inputSubMenuT)[]

import { isValidElement, type ReactNode } from 'react'
import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function isAllowedPrimitive(value: unknown): value is allowedPrimitiveT {
  return ['string', 'number', 'boolean'].includes(typeof value)
}

export function parseAllowedPrimitive(value: allowedPrimitiveT): allowedPrimitiveT {
  if (typeof value !== 'string') return value

  const trimmed = value.trim()

  if (trimmed === 'true') return true
  if (trimmed === 'false') return false
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed)

  return trimmed
}

export function itemTypeChecker<T>(key: keyof T) {
  return (option: any): option is T => !!option && typeof option === 'object' && key in option
}

export const isSeparator = (item: any) => item === '---'
export const isOption = itemTypeChecker<itemT>('value')
export const isGroup = itemTypeChecker<groupT>('group')

export const getValue = (item: allowedPrimitiveT | itemT) =>
  typeof item === 'object' ? item.value : item
export const getLabel = (item: allowedPrimitiveT | itemT) =>
  typeof item === 'object' ? item.label : `${item}`

export function getKey(item: allowedPrimitiveT | itemT, i: number): string {
  const val = getValue(item)
  if (typeof val === 'boolean') return `key-${val}`
  if (val === '---') return `---${i}`
  return `${val}`
}

export function extractText(node: ReactNode): string {
  if (node == null || typeof node === 'boolean') return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (isValidElement(node)) return extractText((node.props as { children?: ReactNode }).children)
  if (Array.isArray(node)) return node.map(extractText).join('')
  return ''
}

import { itemTypeChecker } from './utils'

export const isSubMenu = itemTypeChecker<subMenuT>('submenu')
export const isGroupMenu = itemTypeChecker<menuGroupT>('group')
export const isInputSubMenu = itemTypeChecker<inputSubMenuT>('submenu')
export const isInputGroupMenu = itemTypeChecker<menuInputGroupT>('group')

